#!/usr/bin/env python3
"""Render the addendum's approved runtime/coverage setup from measured evidence."""
import json
from experiment import EXPERIMENT
if __name__=='__main__':
 fetch=json.loads((EXPERIMENT/'results/classpath-fetch.json').read_text());coverage=json.loads((EXPERIMENT/'results/coverage-smoke.json').read_text());artifacts=json.loads((EXPERIMENT/'tools/classpath-artifacts.json').read_text())
 lines=['# Generated-test classpath and coverage tools','','The Part 1 addendum removes EvoSuite: it is a KTester-internal dependency and the generated smoke test compiled and ran without it. The supplied JaCoCo snapshot artifacts are replaced by the explicitly approved release artifacts. The original supplied-jar inventory remains in jar-inventory.json/md as provenance, not the current fetch plan.','','Current configuration: classpath-artifacts.json and llm-classpath.txt. Artifacts with role=test are the only jars on compile/run classpaths. Artifacts with role=coverage are used solely via -javaagent or java -jar. Do not use work/libs/* for compilation now that this directory also contains coverage tools.','','Measurement commands (from KTester/docker):','','```sh',"docker compose run --rm -v /Users/donggi/_projects/experiment-projects/commons-codec:/repo ktester bash -c '/repo/experiments/ktester-commit-survival/tools/fetch-llm-classpath.sh && python /repo/experiments/ktester-commit-survival/tools/coverage_smoke.py'",'```','','Every number below is rendered by `python3 experiments/ktester-commit-survival/tools/classpath_report.py` from results/classpath-fetch.json and results/coverage-smoke.json. The fetcher uses the existing shared Maven cache and Maven Central. Every fetched file has its byte size and SHA-256 recorded; test-runtime artifacts retain their original supplied digests.','',f"All {fetch['resolved']} of {fetch['requested']} approved artifacts are present: {sum(a['role']=='test' for a in artifacts)} test-runtime jars and {sum(a['role']=='coverage' for a in artifacts)} coverage tools.",'','| Role | Coordinate | Classifier | Local filename |','|---|---|---|---|']
 for a in artifacts:lines.append(f"| {a['role']} | {a['coordinate']} | {a['classifier']} | {a['filename']} |")
 lines+=['','## Verified commands','','Working directory inside the container: /repo/experiments/ktester-commit-survival. These exact commands compiled the original smoke class, ran it with the coverage agent, and emitted source-line XML:','','```sh',*[r['shell_command'] for r in coverage['runs']],'```','',f"Md5Crypt.java has {coverage['line_entries']} line entries; {coverage['counters']['LINE']['covered']} covered lines and {coverage['counters']['INSTRUCTION']['covered']} covered instructions. The exact covered line numbers and all counters are in results/coverage-smoke.json. The XML is work/smoke/jacoco.xml; execution data is work/smoke/jacoco.exec. The compile and report commands exit successfully. The smoke class still has assertion failures, allowed by the smoke criterion; tests execute and produce non-zero coverage.",'','The original smoke source remains under ignored work/smoke/ only. No jar or authored generated test source is committed. Current coverage measurement does not rebuild the KTester project index or make model calls. Public logs normalize trailing whitespace; raw logs remain under ignored work/raw-logs/.','','## First attempt','','The initial exact-inventory fetch stopped after repeated failures resolving EvoSuite and the supplied JaCoCo snapshots. The first attempt is preserved in commit 05e849ed and its failure logs. The addendum explicitly resolves that stop through exclusion and released-version substitution; those old failure logs are historical evidence, not current unresolved dependencies.']
 (EXPERIMENT/'tools/README.md').write_text('\n'.join(lines)+'\n')
